import subprocess

# Check the wave JSON for the vps-actual-state task definition
result = subprocess.run(["cat", "/mnt/e/VPS/p5-alpha-execution-headless-wave-20260814.json"], 
                        capture_output=True, text=True, timeout=10)
import json
try:
    data = json.loads(result.stdout)
    tasks = data.get("tasks", [])
    for t in tasks:
        if "vps" in t.get("task_id", "").lower():
            print(json.dumps(t, indent=2, ensure_ascii=False)[:2000])
            print("---")
except:
    # Try searching for the vps-actual-state task
    lines = result.stdout.split('\n')
    for i, l in enumerate(lines):
        if "vps" in l.lower():
            print('\n'.join(lines[max(0,i-2):i+10]))
            print("---")

